// Which businesses even claim this trade. The service-area test cannot happen here any more:
// the new record keeps the service area per trade, inside services/{trade}/jsondata/extracted,
// so testing it costs a document read per business. That read is the next node — this one only
// narrows the list down to the businesses worth reading.
const input = $('When Called by Subagent').first().json;
const TRADE = String(input.trade || '').toLowerCase().trim();
if (!TRADE) return [{ json: { noMatch: true, noMatchReason: 'trade' } }];

const slug = (value) =>
  String(value == null ? '' : value).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

// Firestore values arrive plain through the n8n node, but a raw REST shape ({ doubleValue })
// costs one line to tolerate and saves a whole class of "why is everything zero".
const num = (value) => {
  const raw = value !== null && typeof value === 'object'
    ? (value.doubleValue ?? value.integerValue ?? value.stringValue ?? null)
    : value;
  const parsed = Number(raw);
  return Number.isFinite(parsed) ? parsed : null;
};

// No coordinates is a different failure from "nobody covers you", and the customer is told so
// rather than being shown an empty page. Checked here, before any reads are paid for.
const place = input.place || null;
const lat = place ? num(place.latitude) : null;
const lng = place ? num(place.longitude) : null;
if (lat === null || lng === null) return [{ json: { noMatch: true, noMatchReason: 'place' } }];

const candidates = [];
for (const item of $input.all()) {
  const business = item.json || {};
  // The document id IS the uid, so a record that never wrote the field is still addressable.
  // Without this a business with no uid field builds the path 'businesses//services/...' and
  // every read for it fails in a way that looks exactly like nobody covering the customer.
  const uid = business.uid || business._id || null;
  if (!uid) continue;
  const services = Array.isArray(business.services_provided) ? business.services_provided.map(slug) : [];
  if (!services.includes(TRADE)) continue;
  candidates.push({ json: { ...business, uid } });
}

// Nobody is registered for this trade at all. From where the customer sits that is the same
// answer as "nobody near you", so it gets the same reason code.
if (candidates.length === 0) return [{ json: { noMatch: true, noMatchReason: 'suburb' } }];
return candidates;

// A reason, not a sentence. "No fencing business has registered that suburb" and "No tiler
// covers that suburb" are the same result worded differently, and wording belongs to the
// trade — so the subagent writes it.
return [{
  json: {
    matched: false,
    noMatchReason: $input.first().json.noMatchReason || 'area',
    businesses: [],
    pricing: [],
    totalCovering: 0,
    nearby: [],
    diagnostics: $input.first().json.diagnostics || null,
  },
}];

// Everything the caller needs in one item: the businesses whose own service area reaches this
// customer, and the document each of them published for this trade. They are index-aligned —
// pricing[i] belongs to businesses[i].
//
// The service area moved. It used to sit on the business record with a Google placeId, so a
// business was matched by suburb first and radius second. The new record keeps it per trade, as
// a resolved lat/lng plus a radius in KILOMETRES, and carries no placeId at all — so distance
// is now the only test there is, and a business 20km away in the next suburb now matches where
// before it silently did not.
const input = $('When Called by Subagent').first().json;
const TRADE = String(input.trade || '').toLowerCase().trim();
const checklist = input.checklist || {};
const place = input.place || {};

const slug = (value) =>
  String(value == null ? '' : value).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

// Firestore values arrive plain through the n8n node, but a raw REST shape ({ doubleValue })
// costs one line to tolerate and saves a whole class of "why is everything zero".
const num = (value) => {
  const raw = value !== null && typeof value === 'object'
    ? (value.doubleValue ?? value.integerValue ?? value.stringValue ?? null)
    : value;
  const parsed = Number(raw);
  return Number.isFinite(parsed) ? parsed : null;
};

// Haversine, in metres. A spherical earth is well inside the error a 30 km service radius
// already tolerates.
const distanceMeters = (fromLat, fromLng, toLat, toLng) => {
  const R = 6371000;
  const rad = (deg) => (deg * Math.PI) / 180;
  const dLat = rad(toLat - fromLat);
  const dLng = rad(toLng - fromLng);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(fromLat)) * Math.cos(rad(toLat)) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.min(1, Math.sqrt(h)));
};

const lat = num(place.latitude);
const lng = num(place.longitude);
// Without coordinates every distance is NaN, and NaN fails every comparison — which would let
// the whole country through instead of nobody. Belt and braces on top of the earlier check.
if (lat === null || lng === null) {
  return [{ json: { matched: false, noMatchReason: 'place', businesses: [], pricing: [], totalCovering: 0 } }];
}

const candidates = $('Filter Candidates by Trade').all().map((item) => item.json);
const docs = $input.all();

// Which business a document belongs to. Firestore hands back _name — the full document path —
// and the uid is in it, so the pairing is exact and does not care what order the reads came
// back in or whether a failed read emitted an item at all. Position is only the last resort: a
// business paired with somebody else's rates would quote the wrong price with nothing on screen
// to explain it, and that is the one failure here nobody would ever notice.
const uidFromName = (name) => {
  const match = String(name || '').match(/businesses\/([^/]+)\//);
  return match ? match[1] : null;
};
const byUid = new Map(candidates.map((business) => [business.uid, business]));

const businessFor = (item, position) => {
  const named = uidFromName((item.json || {})._name);
  if (named && byUid.has(named)) return byUid.get(named);
  const paired = item.pairedItem;
  const index = typeof paired === 'number' ? paired
    : paired && typeof paired === 'object' && Number.isInteger(paired.item) ? paired.item
      : Array.isArray(paired) && paired.length && Number.isInteger(paired[0].item) ? paired[0].item
        : position;
  return candidates[index];
};

// The only thing still matched by name: a suburb a business has explicitly excluded.
const customerKeys = [place.suburb, place.name, place.postcode, checklist.suburb]
  .filter(Boolean)
  .map(slug);

const matches = [];
// Every suburb a business of this trade actually works out of, whether or not it reaches this
// customer. When nothing matches, this is the difference between "nobody covers you" — which is
// a dead end — and "nobody covers you, here are the three nearest suburbs that are covered".
const covered = [];
// Why each candidate was dropped. Returned with the result so a run that finds nobody can be
// read in n8n without adding logging: exactly one of these counters explains it.
const dropped = { errored: 0, notConfirmed: 0, wrongTrade: 0, noCoords: 0, outsideRadius: 0, excluded: 0 };

for (let position = 0; position < docs.length; position += 1) {
  const item = docs[position];
  const business = businessFor(item, position);
  if (!business || !business.uid) continue;

  const doc = item.json || {};
  // No document for this trade yet is the same as a business that never finished setting its
  // pricing up. Counted rather than ignored — a run where every read errored looks identical to
  // "nobody covers you" from the outside, and they need completely different fixes.
  if (doc.error || (!doc.data && doc.status === undefined)) { dropped.errored += 1; continue; }

  const data = doc.data || {};
  // Confirmed is the new isComplete, and THIS document's own status is the authoritative copy.
  // The one on services/{trade} is a convenience mirror that can lag behind it, so it is not
  // read here — accepting either would let a business back in the moment the mirror went stale.
  if (doc.status !== 'confirmed') { dropped.notConfirmed += 1; continue; }
  // A document filed under the wrong trade would price a job nobody described.
  if (data.trade && slug(data.trade) !== TRADE) { dropped.wrongTrade += 1; continue; }

  /* The service area is recorded in two places and either one is a real answer: the per-trade
     document, which is what the business last confirmed for THIS trade, and the business record
     itself, which is where it lived before the migration. The per-trade copy wins because it is
     the more specific and more recent of the two, but a business whose per-trade geocode never
     resolved is not a business that stopped covering anybody — it still has an address on file,
     and dropping it over a missing sub-field would hide a real trader from a real customer. */
  const area = data.serviceArea || {};
  const resolved = area.resolved || {};
  const rootArea = business.serviceArea || {};
  const rootPoint = rootArea.geopoint || {};

  const areaLat = num(resolved.lat) ?? num(rootArea.latitude) ?? num(rootPoint.latitude);
  const areaLng = num(resolved.lng) ?? num(rootArea.longitude) ?? num(rootPoint.longitude);
  // One is written in kilometres, the other in metres.
  const perTradeKm = num(area.radiusKm);
  const radiusMetres = perTradeKm !== null ? perTradeKm * 1000 : num(rootArea.radiusMeters);

  if (areaLat === null || areaLng === null || radiusMetres === null) { dropped.noCoords += 1; continue; }

  const areaSuburb = resolved.suburb || rootArea.name || null;
  if (areaSuburb) {
    covered.push({
      suburb: String(areaSuburb),
      state: resolved.state || null,
      postcode: resolved.postcode || null,
      latitude: areaLat,
      longitude: areaLng,
      distanceMeters: Math.round(distanceMeters(lat, lng, areaLat, areaLng)),
    });
  }

  // Excluded areas are free text in the business's own words — "the CBD", "the peninsula",
  // "Frankston South" — not place ids and not normalised. So they are matched loosely, in both
  // directions: "frankston" excludes "Frankston South", and "the peninsula" is caught by a
  // customer suburb that appears inside it. A false positive here costs one business a lead; a
  // false negative sends them somewhere they said they will not go.
  const excluded = (Array.isArray(area.excludedAreas) ? area.excludedAreas : [])
    .map((entry) => (entry && typeof entry === 'object' ? (entry.name || entry.suburb || entry.postcode) : entry))
    .filter(Boolean)
    .map(slug)
    .filter((entry) => entry.length > 2);
  const excludedHere = excluded.some((entry) =>
    customerKeys.some((key) => key.length > 2 && (entry.includes(key) || key.includes(entry))));
  if (excludedHere) { dropped.excluded += 1; continue; }

  const distance = distanceMeters(lat, lng, areaLat, areaLng);
  if (distance > radiusMetres) { dropped.outsideRadius += 1; continue; }

  matches.push({
    business: {
      uid: business.uid,
      businessName: business.businessName || 'Unnamed business',
      rating: num(business.rating),
      reviewCount: num(business.reviewCount),
      isAutoAcceptEnabled: business.isAutoAcceptEnabled === true,
      autoAcceptsAi: business.isAiAutoAcceptEnabled === true,
      distanceMeters: Math.round(distance),
      distanceKm: Math.round(distance / 100) / 10,
      suburb: place.displayLabel || checklist.suburb || '',
    },
    // The whole document, tagged with the shape it is in, so the trade workflow reading it never
    // has to guess which generation of the data it was handed.
    pricing: { shape: 'v2', ...data },
  });
}

// The suburbs this trade is actually worked out of, nearest first, one entry each. Offered to a
// customer nobody covers so the conversation has somewhere to go — the coordinates travel with
// them, so picking one needs no second trip to Google.
const nearby = [];
const seenSuburb = new Set();
for (const area of covered.sort((a, b) => a.distanceMeters - b.distanceMeters)) {
  const key = slug(area.suburb);
  if (!key || seenSuburb.has(key)) continue;
  seenSuburb.add(key);
  nearby.push({ ...area, distanceKm: Math.round(area.distanceMeters / 100) / 10 });
  if (nearby.length >= 6) break;
}

if (matches.length === 0) {
  return [{
    json: {
      matched: false,
      noMatchReason: dropped.outsideRadius > 0 || dropped.excluded > 0 ? 'radius'
        : dropped.notConfirmed > 0 ? 'pricing' : 'suburb',
      businesses: [],
      pricing: [],
      totalCovering: 0,
      nearby,
      // Read this in n8n when a run finds nobody unexpectedly. candidates is how many businesses
      // claim the trade at all; exactly one of the dropped counters accounts for the rest.
      diagnostics: {
        candidates: candidates.length,
        documents: docs.length,
        ...dropped,
        // The first document exactly as Firestore handed it over. When every counter looks
        // wrong, this is the thing to read: it shows whether the nested maps arrived at all.
        sample: docs.length ? {
          keys: Object.keys(docs[0].json || {}),
          status: (docs[0].json || {}).status ?? null,
          dataKeys: Object.keys(((docs[0].json || {}).data) || {}),
          serviceArea: (((docs[0].json || {}).data) || {}).serviceArea ?? null,
          error: (docs[0].json || {}).error ?? null,
        } : null,
      },
    },
  }];
}

// Nearest first, so the list reads sensibly if anything downstream shows it unsorted. Price,
// not distance, decides the actual ranking — that happens in the trade workflow.
matches.sort((a, b) => a.business.distanceMeters - b.business.distanceMeters);

return [{
  json: {
    matched: true,
    noMatchReason: null,
    businesses: matches.map((entry) => entry.business),
    pricing: matches.map((entry) => entry.pricing),
    // Every business that covers them, including ones that cannot quote this particular job.
    // That is what "screened" honestly means on the results page.
    totalCovering: matches.length,
    nearby,
    diagnostics: { candidates: candidates.length, documents: docs.length, ...dropped },
  },
}];

// The pre-migration path, still used by tiling, decking and retaining walls until their data
// moves to services/{trade}/jsondata/extracted as well. Unchanged behaviour on purpose:
//   1. SUBURB — the business's registered service area must BE the customer's suburb.
//   2. RADIUS — inside that suburb, its own travel radius must still reach them.
// Do not "fix" this to match the v2 path. These businesses were matched this way when their
// radii were set, and loosening it here would show them jobs they never agreed to travel for.
const input = $('When Called by Subagent').first().json;
const checklist = input.checklist || {};
const place = input.place || null;

const slug = (value) =>
  String(value == null ? '' : value).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

// Firestore values arrive plain through the n8n node, but a raw REST shape ({ doubleValue })
// costs one line to tolerate and saves a whole class of "why is everything zero".
const num = (value) => {
  const raw = value !== null && typeof value === 'object'
    ? (value.doubleValue ?? value.integerValue ?? value.stringValue ?? null)
    : value;
  const parsed = Number(raw);
  return Number.isFinite(parsed) ? parsed : null;
};

// Haversine, in metres. A spherical earth is well inside the error a 30 km service radius
// already tolerates.
const distanceMeters = (fromLat, fromLng, toLat, toLng) => {
  const R = 6371000;
  const rad = (deg) => (deg * Math.PI) / 180;
  const dLat = rad(toLat - fromLat);
  const dLng = rad(toLng - fromLng);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(fromLat)) * Math.cos(rad(toLat)) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.min(1, Math.sqrt(h)));
};

const lat = place ? num(place.latitude) : null;
const lng = place ? num(place.longitude) : null;
if (lat === null || lng === null) return [{ json: { noMatch: true, noMatchReason: 'place' } }];

const wantedPlaceId = String((place && place.placeId) || '').trim();
const wantedSuburb = slug((place && (place.suburb || place.name)) || checklist.suburb);

const matches = [];
let outsideRadius = 0;
for (const item of $input.all()) {
  const business = item.json || {};

  const area = business.serviceArea || {};
  const areaPlaceId = String(area.id || '').trim();
  const sameSuburb = areaPlaceId && wantedPlaceId
    ? areaPlaceId === wantedPlaceId
    : !!wantedSuburb && slug(area.name) === wantedSuburb;
  if (!sameSuburb) continue;

  const areaLat = num(area.latitude);
  const areaLng = num(area.longitude);
  const radius = num(area.radiusMeters);
  if (areaLat === null || areaLng === null || radius === null) continue;

  const distance = distanceMeters(lat, lng, areaLat, areaLng);
  if (distance > radius) { outsideRadius += 1; continue; }

  matches.push({
    json: {
      uid: business.uid,
      businessName: business.businessName || 'Unnamed business',
      rating: num(business.rating),
      reviewCount: num(business.reviewCount),
      isAutoAcceptEnabled: business.isAutoAcceptEnabled === true,
      autoAcceptsAi: business.isAiAutoAcceptEnabled === true,
      distanceMeters: Math.round(distance),
      distanceKm: Math.round(distance / 100) / 10,
      suburb: (place && place.displayLabel) || checklist.suburb || '',
    },
  });
}

if (matches.length === 0) {
  return [{ json: { noMatch: true, noMatchReason: outsideRadius > 0 ? 'radius' : 'suburb' } }];
}
matches.sort((a, b) => a.json.distanceMeters - b.json.distanceMeters);
return matches;

// Both lists come back as one item so the caller gets a single, predictable shape. They are
// index-aligned: pricing[i] belongs to businesses[i]. Tagged v1 so a trade workflow reading a
// document knows which generation of the shape it is looking at.
const businesses = $('Filter Legacy Service Area').all().map((item) => item.json);
const pricing = $input.all().map((item) => ({ shape: 'v1', ...(item.json || {}) }));

return [{
  json: {
    matched: true,
    noMatchReason: null,
    businesses,
    pricing,
    // Every business that covers them, including ones that cannot quote this particular job.
    // That is what "screened" honestly means on the results page.
    totalCovering: businesses.length,
    nearby: [],
  },
}];
